import sys
from collections import OrderedDict

def main():
    data = sys.stdin.read().splitlines()
    capacity = int(data[0])
    q = int(data[1])
    cache = OrderedDict()
    out = []
    for i in range(2, 2 + q):
        line = data[i].split()
        op = line[0]
        if op == 'GET':
            k = int(line[1])
            if k in cache:
                cache.move_to_end(k)
                out.append(str(cache[k]))
            else:
                out.append('-1')
        elif op == 'PUT':
            k, v = int(line[1]), int(line[2])
            if k in cache:
                cache.move_to_end(k)
                cache[k] = v
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[k] = v
    print('\n'.join(out))

main()
